/// A trait for types that can provide AWS credentials.
pub trait CredentialsProvider {
    /// Attempt to load AWS credentials.
    fn load_credentials(&self) -> Result<AwsCredentials, Box<dyn Error>>;
}

/// A type that can load credentials from multiple sources.
pub struct CredentialsLoader {
    providers: Vec<Box<dyn CredentialsProvider>>,
}

impl CredentialsLoader {
    /// Create a new `CredentialsLoader` with the given providers.
    pub fn new(providers: Vec<Box<dyn CredentialsProvider>>) -> CredentialsLoader {
        CredentialsLoader { providers }
    }

    /// Load credentials from the first provider that succeeds.
    pub fn load_credentials(&self) -> Result<AwsCredentials, Box<dyn Error>> {
        for provider in &self.providers {
            match provider.load_credentials() {
