/// diff_left returns keys that are in the left iterator but not in the right iterator
fn diff_left<'a>(left: impl Iterator<Item = &'a String>, right: &'a Vec<String>) -> Vec<String> {
    let mut diff = Vec::<String>::new();
    for key in left {
        if !right.contains(&key.to_string()) {
            diff.push(key.to_string());
        }
    }
    diff
}

