    fn from_fixed_header_and_stream<R: Read>(
        fixed_header: FixedHeader,
        reader: &mut R,
    ) -> Result<Self, PacketError> {
        let packet_identifier = PacketIdentifier::decode(reader)
            .map_err(|e| PacketError::from(e))?;
        let payload = SubackPacketPayload::decode(reader)
            .map_err(|e| PacketError::from(e))?;

        Ok(SubackPacket {
            fixed_header,
            packet_identifier,
            payload,
        })
    }
}

