fn award_points(reindeers: &mut Vec<Reindeer>) {
    let mut max_distance = 0;
    for r in reindeers.iter() {
        if r.current_distance > max_distance {
            max_distance = r.current_distance;
        }
    }

    for r in reindeers.iter_mut() {
        if r.current_distance >= max_distance {
            r.points += 1;
