fn check_static_mut_item(cx: &ty::ctxt, i: &ast::Item) {
    // Mutable statics can only contain certain types.
    //
    // - They cannot contain types with destructors, because if the static
    // is dropped, its destructor would run after the program has exited,
    // which is Undefined Behavior.
    //
    // - They cannot contain owned pointers (like String, Vec, Box), because
    // these types manage memory. If the static is dropped, these types would
    // try to deallocate memory after the program has exited, which is Undefined
    // Behavior.
    //
    // Immutable statics are more relaxed because they are not mutated.
    // Their values are computed once at compile time.
    //
    // `static mut` requires a type that can be initialized at compile time.
