    ( $name:ident [$size:expr] $($extra:tt)* ) => {
        struct $name([u8; $size]);
        impl_byte_array!($name[$size] $($extra)*);
    };
    ( pub $name:ident [$size:expr] $($extra:tt)* ) => {
        pub struct $name([u8; $size]);
        impl_byte_array!($name[$size] $($extra)*);
    };
}

